#include <vector>

using namespace std;

class Solution {
public:
    double averageWaitingTime(vector<vector<int>>& customers) {
        long long time = 0, wait = 0;
        for (auto& c : customers) {
            time = max(time, (long long)c[0]) + c[1];
            wait += time - c[0];
        }
        return (double)wait / customers.size();
    }
};
